from pathlib import Path
p = Path("src/gepaw/token_usage/model_wrapper.py")
data = p.read_bytes()
old = b'''def record_usage(\r\n    provider_id: str,\r\n    model_name: str,\r\n    prompt_tokens: int = 0,\r\n    completion_tokens: int = 0,\r\n    cache_read_tokens: int = 0,\r\n    cache_write_tokens: int = 0,\r\n    cost_cents: float = 0.0,\r\n    session_id: str = \'\',\r\n    user_id: str = \'\',\r\n    agent_id: str = \'\',\r\n    raw: dict = None,\r\n) -> None:\r\n    """Convenience wrapper to record a usage event via the manager."""\r\n    from .manager import get_token_usage_manager\r\n\r\n    manager = get_token_usage_manager()\r\n    manager.enqueue(\r\n        provider_id=provider_id,\r\n        model_name=model_name,\r\n        prompt_tokens=prompt_tokens,\r\n        completion_tokens=completion_tokens,\r\n        cache_read_tokens=cache_read_tokens,\r\n        cache_write_tokens=cache_write_tokens,\r\n        cost_cents=cost_cents,\r\n        session_id=session_id,\r\n        user_id=user_id,\r\n        agent_id=agent_id,\r\n        raw=raw or {},\r\n    )'''
new = b'''def record_usage(\r\n    db = None,\r\n    *,\r\n    org_id: str = "",\r\n    model: str = "",\r\n    provider_id: str = "",\r\n    model_name: str = "",\r\n    prompt_tokens: int = 0,\r\n    completion_tokens: int = 0,\r\n    cache_read_tokens: int = 0,\r\n    cache_write_tokens: int = 0,\r\n    cost_cents: float = 0.0,\r\n    session_id = "",\r\n    user_id = None,\r\n    agent_id: str = "",\r\n    raw: dict = None,\r\n) -> int:\r\n    """Convenience wrapper to record a usage event via the manager.\r\n\r\n    Supports two call shapes:\r\n\r\n    1. New style (with ``db``) -- inserts a row directly and returns its id.\r\n    2. Legacy style (no ``db``) -- enqueues an event on the background\r\n       manager for fire-and-forget recording.\r\n    """\r\n    if not model_name and model:\r\n        model_name = model\r\n    if not provider_id and model:\r\n        provider_id = model\r\n\r\n    if db is not None:\r\n        from .manager import TokenUsageLog\r\n        row = TokenUsageLog(\r\n            org_id=org_id,\r\n            user_id=user_id,\r\n            session_id=str(session_id or ""),\r\n            agent_id=agent_id or "",\r\n            model_name=model_name,\r\n            provider_id=provider_id or model_name,\r\n            prompt_tokens=prompt_tokens,\r\n            completion_tokens=completion_tokens,\r\n            cache_read_tokens=cache_read_tokens,\r\n            cache_write_tokens=cache_write_tokens,\r\n            cost_cents=cost_cents,\r\n            raw=raw or {},\r\n        )\r\n        db.add(row)\r\n        try:\r\n            db.flush()\r\n        except Exception:\r\n            pass\r\n        return getattr(row, "id", 0) or 0\r\n\r\n    from .manager import get_token_usage_manager\r\n    manager = get_token_usage_manager()\r\n    manager.enqueue(\r\n        provider_id=provider_id or model_name,\r\n        model_name=model_name,\r\n        prompt_tokens=prompt_tokens,\r\n        completion_tokens=completion_tokens,\r\n        cache_read_tokens=cache_read_tokens,\r\n        cache_write_tokens=cache_write_tokens,\r\n        cost_cents=cost_cents,\r\n        session_id=str(session_id or ""),\r\n        user_id=str(user_id) if user_id is not None else "",\r\n        agent_id=agent_id or "",\r\n        raw=raw or {},\r\n    )\r\n    return 0'''
print("found:", old in data)
data = data.replace(old, new)
p.write_bytes(data)
print("done")
